import pandas as pd
import json
import os
from jinja2 import Template

# Ensure output directory exists
os.makedirs('/app/output', exist_ok=True)

# Load data
df = pd.read_csv('/app/benchmark/data.csv')

# Clean data
df['price'] = pd.to_numeric(df['price'], errors='coerce')
df['reviews_per_month'] = pd.to_numeric(df['reviews_per_month'], errors='coerce').fillna(0)
df['calculated_host_listings_count'] = pd.to_numeric(df['calculated_host_listings_count'], errors='coerce').fillna(0)
df['availability_365'] = pd.to_numeric(df['availability_365'], errors='coerce').fillna(0)

# KPIs per city
kpis_df = df.groupby('city').agg(
    total_listings=('id', 'count'),
    median_price=('price', 'median'),
    mean_price=('price', 'mean'),
    prof_host_share=('calculated_host_listings_count', lambda x: (x >= 5).mean() * 100),
    avg_reviews_pm=('reviews_per_month', 'mean'),
    mean_availability=('availability_365', 'mean'),
    entire_home_share=('room_type', lambda x: (x == 'Entire home/apt').mean() * 100)
).reset_index()

# Sort by median price descending
kpis_df = kpis_df.sort_values(by='median_price', ascending=False)
cities = kpis_df['city'].tolist()

kpis = {row['city']: row.to_dict() for _, row in kpis_df.iterrows()}

# Charts Data
market_overview_data = {
    'labels': kpis_df['city'].tolist(),
    'data': kpis_df['total_listings'].tolist()
}

pricing_dynamics_data = {
    'labels': kpis_df['city'].tolist(),
    'data': [round(x, 2) if pd.notnull(x) else 0 for x in kpis_df['median_price'].tolist()]
}

pricing_room_type = df.groupby(['city', 'room_type'])['price'].median().unstack().fillna(0)
# Sort pricing_room_type by the same order as cities
pricing_room_type = pricing_room_type.loc[cities]

pricing_room_type_data = {
    'labels': pricing_room_type.index.tolist(),
    'datasets': [
        {
            'label': room_type,
            'data': pricing_room_type[room_type].tolist()
        } for room_type in pricing_room_type.columns
    ]
}

supply_structure_data = {
    'labels': kpis_df['city'].tolist(),
    'data': [round(x, 2) for x in kpis_df['prof_host_share'].tolist()]
}

guest_demand_data = {
    'labels': kpis_df['city'].tolist(),
    'data': [round(x, 2) for x in kpis_df['avg_reviews_pm'].tolist()]
}

availability_data = {
    'labels': kpis_df['city'].tolist(),
    'data': [round(x, 2) for x in kpis_df['mean_availability'].tolist()]
}

# Global Metrics
total_listings_global = len(df)
global_avg_median_price = kpis_df['median_price'].mean()
global_prof_host_share = (df['calculated_host_listings_count'] >= 5).mean() * 100
global_avg_reviews = df['reviews_per_month'].mean()
global_entire_home = (df['room_type'] == 'Entire home/apt').mean() * 100

most_expensive_city = kpis_df.iloc[0]['city']
least_expensive_city = kpis_df.iloc[-1]['city']

highest_prof_city_row = kpis_df.loc[kpis_df['prof_host_share'].idxmax()]
highest_prof_city = highest_prof_city_row['city']
highest_prof_share = highest_prof_city_row['prof_host_share']

highest_demand_city_row = kpis_df.loc[kpis_df['avg_reviews_pm'].idxmax()]
highest_demand_city = highest_demand_city_row['city']
highest_demand_val = highest_demand_city_row['avg_reviews_pm']

# Template
html_template = """
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>Global Airbnb Cross-Market Analysis</title>
    <script src="https://cdn.jsdelivr.net/npm/chart.js"></script>
    <style>
        :root {
            --primary: #2c3e50;
            --secondary: #34495e;
            --accent: #3498db;
            --bg: #f8f9fa;
            --card-bg: #ffffff;
            --text: #333333;
            --text-light: #7f8c8d;
        }
        body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", sans-serif; background-color: var(--bg); color: var(--text); margin: 0; padding: 0; line-height: 1.6; }
        .container { max-width: 1200px; margin: 0 auto; padding: 40px 20px; }
        .header { text-align: center; margin-bottom: 50px; }
        .header h1 { font-size: 42px; margin: 0 0 15px 0; color: var(--primary); letter-spacing: -0.5px; }
        .header p { font-size: 20px; color: var(--text-light); max-width: 800px; margin: 0 auto; }
        .kpi-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 24px; margin-bottom: 50px; }
        .kpi-card { background: var(--card-bg); border-radius: 12px; box-shadow: 0 4px 6px rgba(0,0,0,0.05); padding: 24px; text-align: center; border: 1px solid #e1e8ed; }
        .kpi-card h3 { font-size: 13px; text-transform: uppercase; letter-spacing: 1px; color: var(--text-light); margin: 0 0 10px 0; }
        .kpi-card .value { font-size: 32px; font-weight: 700; color: var(--accent); margin: 0; }
        .section { background: var(--card-bg); border-radius: 12px; box-shadow: 0 4px 6px rgba(0,0,0,0.05); padding: 40px; margin-bottom: 40px; border: 1px solid #e1e8ed; }
        .section h2 { margin-top: 0; color: var(--primary); border-bottom: 2px solid var(--bg); padding-bottom: 15px; margin-bottom: 25px; font-size: 24px; }
        .section > p { color: var(--text-light); margin-bottom: 30px; font-size: 16px; }
        .chart-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 30px; margin-bottom: 20px; }
        .chart-container { position: relative; height: 350px; width: 100%; }
        .chart-container.full-width { grid-column: 1 / -1; height: 400px; }
        .table-responsive { overflow-x: auto; margin-top: 30px; }
        table { width: 100%; border-collapse: separate; border-spacing: 0; font-size: 15px; }
        th, td { padding: 16px; text-align: left; border-bottom: 1px solid #e1e8ed; }
        th { background-color: var(--bg); color: var(--primary); font-weight: 600; text-transform: uppercase; font-size: 13px; letter-spacing: 0.5px; }
        th:first-child { border-top-left-radius: 8px; }
        th:last-child { border-top-right-radius: 8px; }
        tr:hover td { background-color: #f8f9fa; }
        .takeaways { background: #ebf5fb; border-left: 6px solid var(--accent); padding: 30px; border-radius: 0 8px 8px 0; }
        .takeaways ol { margin: 0; padding-left: 20px; }
        .takeaways li { margin-bottom: 15px; font-size: 16px; color: var(--secondary); }
        .takeaways li:last-child { margin-bottom: 0; }
        .takeaways strong { color: var(--primary); }

        @media (max-width: 768px) {
            .chart-grid { grid-template-columns: 1fr; }
            .header h1 { font-size: 32px; }
        }
    </style>
</head>
<body>
    <div class="container">
        <div class="header">
            <h1>Global Airbnb Market Comparison</h1>
            <p>Pricing, Supply & Guest Demand Across 10 Major Cities</p>
        </div>

        <!-- KPIs Section -->
        <div class="kpi-grid">
            <div class="kpi-card">
                <h3>Global Listings</h3>
                <p class="value">{{ "{:,.0f}".format(total_listings_global) }}</p>
            </div>
            <div class="kpi-card">
                <h3>Avg Median Price</h3>
                <p class="value">${{ "{:.0f}".format(global_avg_median_price) }}</p>
            </div>
            <div class="kpi-card">
                <h3>Global Prof Host Share</h3>
                <p class="value">{{ "{:.1f}".format(global_prof_host_share) }}%</p>
            </div>
            <div class="kpi-card">
                <h3>Global Avg Reviews/Mo</h3>
                <p class="value">{{ "{:.2f}".format(global_avg_reviews) }}</p>
            </div>
            <div class="kpi-card">
                <h3>Global Entire Home Share</h3>
                <p class="value">{{ "{:.1f}".format(global_entire_home) }}%</p>
            </div>
        </div>

        <div class="section" id="market-overview">
            <h2>1. Global Market Overview</h2>
            <p>Summary of total listings across the 10 target markets. This establishes the scale and composition of each market.</p>
            <div class="chart-container full-width">
                <canvas id="marketOverviewChart"></canvas>
            </div>
        </div>

        <div class="section" id="pricing-analysis">
            <h2>2. Pricing Dynamics Across Cities</h2>
            <p>Cross-city price comparisons identifying the most and least expensive markets by overall median and room type.</p>
            <div class="chart-grid">
                <div class="chart-container">
                    <canvas id="pricingChart"></canvas>
                </div>
                <div class="chart-container">
                    <canvas id="pricingRoomTypeChart"></canvas>
                </div>
            </div>
        </div>

        <div class="section" id="supply-structure">
            <h2>3. Supply Structure & Host Concentration</h2>
            <p>Percentage of listings managed by professional hosts (5+ listings). A higher concentration suggests a mature, highly commercialized local market.</p>
            <div class="chart-container full-width">
                <canvas id="supplyChart"></canvas>
            </div>
        </div>

        <div class="section" id="guest-demand">
            <h2>4. Guest Demand & Review Activity</h2>
            <p>Average reviews per month serves as a direct proxy for guest engagement, turnover velocity, and overall booking volume.</p>
            <div class="chart-container full-width">
                <canvas id="demandChart"></canvas>
            </div>
        </div>

        <div class="section" id="availability-minimumnights">
            <h2>5. Availability & Booking Constraints</h2>
            <p>Mean availability in days/year. Lower availability might suggest higher occupancy or long-term rental conversions, while high availability often indicates dedicated short-term rental properties.</p>
            <div class="chart-container full-width">
                <canvas id="availabilityChart"></canvas>
