        new Chart(document.getElementById('pricingChart'), {
            type: 'bar',
            data: {
                labels: pricingData.labels,
                datasets: [{
                    label: 'Median Nightly Price (USD)',
                    data: pricingData.data,
                    backgroundColor: '#e74c3c',
                    borderRadius: 4
                }]
            },
            options: {
                ...commonOptions,
                indexAxis: 'y',
                scales: {
                    x: { beginAtZero: true, grid: { color: '#f1f4f6' } },
                    y: { grid: { display: false } }
                }
            }
        });

        // 2b. Pricing by Room Type
        const colors = ['#2ecc71', '#f1c40f', '#9b59b6', '#34495e'];
        new Chart(document.getElementById('pricingRoomTypeChart'), {
            type: 'bar',
            data: {
                labels: pricingRoomTypeData.labels,
                datasets: pricingRoomTypeData.datasets.map((ds, i) => ({
                    ...ds,
                    backgroundColor: colors[i % colors.length],
                    borderRadius: 4
                }))
            },
            options: {
                ...commonOptions,
                plugins: {
                    legend: { position: 'top', labels: { boxWidth: 12, usePointStyle: true } },
                    title: { display: true, text: 'Median Price by Room Type', padding: { bottom: 20 } }
                }
            }
        });

        // 3. Supply Structure
        new Chart(document.getElementById('supplyChart'), {
            type: 'bar',
            data: {
                labels: supplyData.labels,
                datasets: [{
                    label: 'Professional Host Share (%)',
                    data: supplyData.data,
                    backgroundColor: '#9b59b6',
                    borderRadius: 4
                }]
            },
            options: commonOptions
        });

        // 4. Demand
        new Chart(document.getElementById('demandChart'), {
            type: 'bar',
            data: {
                labels: demandData.labels,
                datasets: [{
                    label: 'Avg Reviews per Month',
                    data: demandData.data,
                    backgroundColor: '#f39c12',
                    borderRadius: 4
                }]
            },
            options: commonOptions
        });

        // 5. Availability
        new Chart(document.getElementById('availabilityChart'), {
            type: 'bar',
            data: {
                labels: availabilityData.labels,
                datasets: [{
                    label: 'Mean Availability (days/yr)',
